    // Spring Boot ya autoconfigura un ObjectMapper por defecto para Jackson.
    // Búscalo en /actuator/beans: se llama "jacksonObjectMapper" (lo crea
    // JacksonAutoConfiguration.JacksonObjectMapperConfiguration).
