package tut13.repositorio;

import org.springframework.stereotype.Repository;
import tut13.modelo.Reserva;

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

/** Implementación en memoria: solo existe para que la aplicación arranque. Los tests unitarios no la usan. */
@Repository
public class ReservaRepositoryMemoria implements ReservaRepository {

    private final Map<Long, Reserva> almacen = new ConcurrentHashMap<>();
    private final AtomicLong secuencia = new AtomicLong();

    @Override
    public List<Reserva> findAll() {
        return almacen.values().stream().sorted(Comparator.comparing(Reserva::getId)).toList();
    }

    @Override
    public Optional<Reserva> findById(Long id) {
        return Optional.ofNullable(almacen.get(id));
    }

    @Override
    public Reserva save(Reserva reserva) {
        if (reserva.getId() == null) {
            reserva.setId(secuencia.incrementAndGet());
        }
        almacen.put(reserva.getId(), reserva);
        return reserva;
    }

    @Override
    public void deleteById(Long id) {
        almacen.remove(id);
    }

    @Override
    public int countPersonasActivasByEventoId(Long eventoId) {
        return almacen.values().stream()
                .filter(r -> r.isActiva() && eventoId.equals(r.getEventoId()))
                .mapToInt(Reserva::getNumPersonas)
                .sum();
    }
}
