package tut13.servicio;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import tut13.excepcion.ReservaNotFoundException;
import tut13.modelo.Reserva;
import tut13.repositorio.ReservaRepository;

import java.util.List;

/** Clase bajo prueba en la tutoría: su única dependencia es el repositorio, que en los tests se sustituye por un mock. */
@Service
@Slf4j
public class ReservaServiceImpl implements ReservaService {

    private final ReservaRepository repo;

    public ReservaServiceImpl(ReservaRepository repo) {
        this.repo = repo;
    }

    @Override
    public List<Reserva> findAll() {
        return repo.findAll();
    }

    @Override
    public Reserva findById(Long id) {
        return repo.findById(id).orElseThrow(() -> new ReservaNotFoundException(id));
    }

    @Override
    public Reserva create(Reserva reserva) {
        if (reserva.getNumPersonas() <= 0) {
            throw new IllegalArgumentException("El número de personas debe ser mayor que 0");
        }
        reserva.setActiva(true);
        return repo.save(reserva);
    }

    @Override
    public void cancel(Long id) {
        Reserva reserva = findById(id);
        reserva.setActiva(false);
        repo.save(reserva);
        log.info("Reserva {} cancelada", id);
    }

    @Override
    public void delete(Long id) {
        findById(id);              // lanza ReservaNotFoundException si no existe
        repo.deleteById(id);
    }

    @Override
    public boolean hayCupo(Long eventoId, int personasSolicitadas, int maxPersonas) {
        int reservadas = repo.countPersonasActivasByEventoId(eventoId);
        return (reservadas + personasSolicitadas) <= maxPersonas;
    }
}
