/**
 * Clase SIN dependencias: sirve para practicar JUnit 5 solo (sin Mockito).
 * Cada método tiene lo justo para ilustrar un tipo de test.
 */
public class Calculos {

    /** Caso más simple: entra algo, sale algo. */
    public int sumar(int a, int b) {
        return a + b;
    }

    /** Cuenta las letras 'a' (mayúsculas o minúsculas) de un texto. */
    public int contarLetrasA(String texto) {
        if (texto == null) {
            throw new IllegalArgumentException("El texto no puede ser null");
        }
        int total = 0;
        for (char c : texto.toCharArray()) {
            if (c == 'a' || c == 'A') {
                total++;
            }
        }
        return total;
    }

    /** Método que lanza una excepción: se prueba con assertThrows. */
    public void comprobarPositivo(int numero) {
        if (numero <= 0) {
            throw new IllegalArgumentException("El número debe ser positivo");
        }
    }

    /** Tres caminos posibles (if / else if / else): hacen falta tres tests para cubrirlos todos. */
    public String clasificarOcupacion(int ocupadas, int maximo) {
        if (ocupadas >= maximo) {
            return "LLENO";
        } else if (ocupadas >= maximo * 0.8) {
            return "CASI_LLENO";
        }
        return "LIBRE";
    }
}
