import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;

/** [AVANZADO] Técnicas de Mockito que aparecen menos a menudo pero conviene conocer. */
@ExtendWith(MockitoExtension.class)
@DisplayName("ReservaServiceImpl (técnicas avanzadas de Mockito)")
class ReservaServiceAvanzadoTest {

    @Mock
    private ReservaRepository repo;

    @InjectMocks
    private ReservaServiceImpl service;

    @Test
    @DisplayName("thenThrow: simula un fallo del repositorio y comprueba que el Service lo propaga")
    void create_shouldPropagateException_whenRepositoryFails() {
        // Given
        when(repo.save(any())).thenThrow(new IllegalStateException("BD caída"));
        Reserva reserva = new Reserva(null, 1L, "Ana", 2, false);
        // When + Then
        IllegalStateException ex = assertThrows(IllegalStateException.class, () -> service.create(reserva));
        assertThat(ex).hasMessage("BD caída");
    }

    @Test
    @DisplayName("InOrder: comprueba el ORDEN de las llamadas (primero buscar, después guardar)")
    void cancel_shouldFindBeforeSaving() {
        // Given
        when(repo.findById(1L)).thenReturn(Optional.of(new Reserva(1L, 1L, "Ana", 2, true)));
        // When
        service.cancel(1L);
        // Then
        InOrder orden = inOrder(repo);
        orden.verify(repo).findById(1L);
        orden.verify(repo).save(any(Reserva.class));
    }

    @Test
    @DisplayName("verifyNoMoreInteractions: el Service no hace llamadas de más al repositorio")
    void hayCupo_shouldOnlyAskForCount() {
        // Given
        when(repo.countPersonasActivasByEventoId(1L)).thenReturn(5);
        // When
        service.hayCupo(1L, 1, 10);
        // Then
        verify(repo).countPersonasActivasByEventoId(1L);
        verifyNoMoreInteractions(repo);
    }

    @Test
    @DisplayName("Respuestas consecutivas: el mock contesta distinto en cada llamada")
    void hayCupo_shouldChangeAnswer_whenRepositoryChanges() {
        // Given: primera llamada devuelve 0, segunda llamada devuelve 10
        when(repo.countPersonasActivasByEventoId(1L)).thenReturn(0).thenReturn(10);
        // When + Then
        assertThat(service.hayCupo(1L, 5, 10)).isTrue();    // 0 + 5 <= 10
        assertThat(service.hayCupo(1L, 5, 10)).isFalse();   // 10 + 5 > 10
    }

    @Test
    @DisplayName("lenient: un stub que no se usa NO hace fallar el test")
    void hayCupo_shouldNotFail_withUnusedLenientStub() {
        // Given: este stub no se usa, pero con lenient() Mockito no se queja
        lenient().when(repo.findAll()).thenReturn(List.of());
        // When + Then
        assertThat(service.hayCupo(1L, 1, 10)).isTrue();
    }
}
