import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.mockito.BDDMockito.then;
import static org.mockito.BDDMockito.willDoNothing;
import static org.mockito.Mockito.never;

/**
 * Los mismos casos que ReservaServiceImplTest, pero con BDDMockito:
 * given(...).willReturn(...) en lugar de when(...).thenReturn(...), y then(mock).should() en lugar de verify.
 * Hace exactamente lo mismo; solo cambia la forma de leerse (Given / When / Then también en el código de Mockito).
 */
@ExtendWith(MockitoExtension.class)
@DisplayName("ReservaServiceImpl (estilo BDD)")
class ReservaServiceBddTest {

    @Mock
    private ReservaRepository repo;

    @InjectMocks
    private ReservaServiceImpl service;

    @Test
    @DisplayName("findById devuelve la reserva cuando existe")
    void findById_shouldReturnReserva_whenExists() {
        // Given
        given(repo.findById(1L)).willReturn(Optional.of(DataProvider.reservaMock()));
        // When
        Reserva resultado = service.findById(1L);
        // Then
        assertThat(resultado.getId()).isEqualTo(1L);
    }

    @Test
    @DisplayName("findById lanza ReservaNotFoundException cuando no existe")
    void findById_shouldThrowException_whenNotFound() {
        // Given
        given(repo.findById(99L)).willReturn(Optional.empty());
        // When + Then
        assertThrows(ReservaNotFoundException.class, () -> service.findById(99L));
    }

    @Test
    @DisplayName("delete llama una vez a deleteById")
    void delete_shouldCallRepositoryOnce_whenExists() {
        // Given: willDoNothing es el equivalente BDD de doNothing, para métodos void
        given(repo.findById(1L)).willReturn(Optional.of(DataProvider.reservaMock()));
        willDoNothing().given(repo).deleteById(1L);
        // When
        service.delete(1L);
        // Then
        then(repo).should().deleteById(1L);
    }

    @Test
    @DisplayName("cancel de una reserva inexistente no llega a guardar nada")
    void cancel_shouldNotSave_whenNotFound() {
        // Given
        given(repo.findById(99L)).willReturn(Optional.empty());
        // When
        assertThrows(ReservaNotFoundException.class, () -> service.cancel(99L));
        // Then
        then(repo).should(never()).save(any());
    }
}
