package tut13.servicio;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import tut13.excepcion.ReservaNotFoundException;
import tut13.modelo.Reserva;
import tut13.repositorio.ReservaRepository;

import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Tests unitarios del Service con Mockito CLÁSICO (when / thenReturn).
 * Convención de esta demo: nombre metodo_shouldComportamiento_whenCondicion(), bloques Given / When / Then
 * y una única comprobación principal por test.
 */
@ExtendWith(MockitoExtension.class)               // activa @Mock e @InjectMocks en JUnit 5
@DisplayName("ReservaServiceImpl (Mockito clásico)")
class ReservaServiceImplTest {

    @Mock
    private ReservaRepository repo;                // dependencia -> mock

    @InjectMocks
    private ReservaServiceImpl service;            // clase bajo prueba -> instancia real con el mock dentro

    // ── LECTURA ──────────────────────────────────────────────────────────────

    @Test
    @DisplayName("findAll devuelve las reservas del repositorio")
    void findAll_shouldReturnReservas_whenRepositoryHasData() {
        // Given
        when(repo.findAll()).thenReturn(DataProvider.reservaListMock());
        // When
        List<Reserva> resultado = service.findAll();
        // Then
        assertThat(resultado).hasSize(2);
    }

    @Test
    @DisplayName("findById devuelve la reserva cuando existe")
    void findById_shouldReturnReserva_whenExists() {
        // Given
        when(repo.findById(1L)).thenReturn(Optional.of(DataProvider.reservaMock()));
        // When
        Reserva resultado = service.findById(1L);
        // Then
        assertEquals("Ana García", resultado.getNombreCliente());
    }

    @Test
    @DisplayName("findById lanza ReservaNotFoundException cuando no existe")
    void findById_shouldThrowException_whenNotFound() {
        // Given
        when(repo.findById(99L)).thenReturn(Optional.empty());
        // When + Then
        assertThrows(ReservaNotFoundException.class, () -> service.findById(99L));
    }

    // ── ESCRITURA ────────────────────────────────────────────────────────────

    @Test
    @DisplayName("create guarda la reserva con activa = true")
    void create_shouldSaveActiveReserva_whenInputIsValid() {
        // Given: el mock devuelve lo mismo que recibe
        when(repo.save(any(Reserva.class))).thenAnswer(inv -> inv.getArgument(0));
        // When
        service.create(DataProvider.nuevaReservaMock());
        // Then: ArgumentCaptor captura el objeto con el que se llamó a save
        ArgumentCaptor<Reserva> captor = ArgumentCaptor.forClass(Reserva.class);
        verify(repo).save(captor.capture());
        assertThat(captor.getValue().isActiva()).isTrue();
    }

    @Test
    @DisplayName("create lanza IllegalArgumentException si numPersonas es 0")
    void create_shouldThrowException_whenNumPersonasIsZero() {
        // Given
        Reserva invalida = new Reserva(null, 10L, "Sin personas", 0, false);
        // When + Then
        assertThrows(IllegalArgumentException.class, () -> service.create(invalida));
    }

    @Test
    @DisplayName("create NO llama a save cuando los datos no son válidos")
    void create_shouldNotSave_whenNumPersonasIsZero() {
        // Given
        Reserva invalida = new Reserva(null, 10L, "Sin personas", 0, false);
        // When
        assertThrows(IllegalArgumentException.class, () -> service.create(invalida));
        // Then: never() comprueba que el mock NO fue llamado
        verify(repo, never()).save(any());
    }

    @Test
    @DisplayName("cancel guarda la reserva con activa = false")
    void cancel_shouldSaveInactiveReserva_whenExists() {
        // Given
        when(repo.findById(1L)).thenReturn(Optional.of(DataProvider.reservaMock()));
        // When
        service.cancel(1L);
        // Then
        ArgumentCaptor<Reserva> captor = ArgumentCaptor.forClass(Reserva.class);
        verify(repo).save(captor.capture());
        assertThat(captor.getValue().isActiva()).isFalse();
    }

    @Test
    @DisplayName("cancel lanza ReservaNotFoundException cuando no existe")
    void cancel_shouldThrowException_whenNotFound() {
        // Given
        when(repo.findById(anyLong())).thenReturn(Optional.empty());
        // When + Then
        assertThrows(ReservaNotFoundException.class, () -> service.cancel(99L));
    }

    @Test
    @DisplayName("delete llama a deleteById con el id recibido")
    void delete_shouldCallRepository_whenExists() {
        // Given
        when(repo.findById(1L)).thenReturn(Optional.of(DataProvider.reservaMock()));
        // When: delete es void, no hay valor de retorno que comparar
        service.delete(1L);
        // Then: se comprueba con qué argumento se llamó al mock
        ArgumentCaptor<Long> captor = ArgumentCaptor.forClass(Long.class);
        verify(repo).deleteById(captor.capture());
        assertEquals(1L, captor.getValue());
    }

    // ── REGLA DE NEGOCIO ─────────────────────────────────────────────────────

    @Test
    @DisplayName("hayCupo devuelve true cuando las plazas llegan justas")
    void hayCupo_shouldReturnTrue_whenSpaceAvailable() {
        // Given: 8 personas ya reservadas, máximo 10
        when(repo.countPersonasActivasByEventoId(10L)).thenReturn(8);
        // When: piden 2 más (8 + 2 = 10, no supera el máximo)
        boolean resultado = service.hayCupo(10L, 2, 10);
        // Then
        assertThat(resultado).isTrue();
    }

    @Test
    @DisplayName("hayCupo devuelve false cuando se supera el máximo")
    void hayCupo_shouldReturnFalse_whenNotEnoughSpace() {
        // Given: 9 personas ya reservadas, máximo 10
        when(repo.countPersonasActivasByEventoId(10L)).thenReturn(9);
        // When: piden 2 más (9 + 2 = 11 > 10)
        boolean resultado = service.hayCupo(10L, 2, 10);
        // Then
        assertThat(resultado).isFalse();
    }
}
