package tut14.servicio;
import org.springframework.stereotype.Service;
import tut14.entidad.Libro;
import tut14.excepcion.LibroNotFoundException;
import tut14.repositorio.LibroRepository;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

@Service
public class LibroService {
    private final LibroRepository repo;
    public LibroService(LibroRepository repo) { this.repo = repo; }

    public List<Libro> findAll() { return repo.findAll(); }

    public Libro findById(Long id) {
        return repo.findById(id).orElseThrow(() -> new LibroNotFoundException(id));
    }

    public List<Libro> findByAutor(String autor) { return repo.findByAutorIgnoreCase(autor); }

    public Libro create(Libro libro) { return repo.save(libro); }

    /** Rebaja el precio un porcentaje entre 1 y 90 y devuelve el libro actualizado. */
    public Libro aplicarDescuento(Long id, int porcentaje) {
        if (porcentaje < 1 || porcentaje > 90) {
            throw new IllegalArgumentException("El descuento debe estar entre 1 y 90");
        }
        Libro libro = findById(id);
        BigDecimal factor = BigDecimal.valueOf(100 - porcentaje).divide(BigDecimal.valueOf(100));
        libro.setPrecio(libro.getPrecio().multiply(factor).setScale(2, RoundingMode.HALF_UP));
        return repo.save(libro);
    }

    public void delete(Long id) {
        findById(id);
        repo.deleteById(id);
    }
}
