package tut14.integracion;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.core.ParameterizedTypeReference;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import tut14.entidad.Libro;
import tut14.repositorio.LibroRepository;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests de integración: contexto COMPLETO, servidor real en un puerto aleatorio, sin mocks y contra H2.
 * Cada test es independiente: @BeforeEach vacía la tabla.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Flujos end-to-end de libros (SpringBootTest + TestRestTemplate)")
class LibroIntegrationTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Autowired
    private LibroRepository repo;

    @BeforeEach
    void limpiarBaseDeDatos() {
        repo.deleteAll();
    }

    private Libro libro(String titulo, String autor, String precio) {
        return new Libro(null, titulo, autor, new BigDecimal(precio));
    }

    @Test
    @DisplayName("Alta, descuento, consulta, baja y 404 posterior")
    void lifecycle_shouldReturnCorrectStatusAtEachStep() {
        // When: dar de alta
        ResponseEntity<Libro> creado = restTemplate.postForEntity(
                "/api/v1/libros", libro("Ficciones", "Borges", "20.00"), Libro.class);

        // Then
        assertEquals(HttpStatus.CREATED, creado.getStatusCode());
        Long id = creado.getBody().getId();
        assertNotNull(id);

        // When: aplicar un 10 % de descuento
        ResponseEntity<Libro> rebajado = restTemplate.postForEntity(
                "/api/v1/libros/" + id + "/descuento?porcentaje=10", null, Libro.class);

        // Then
        assertEquals(HttpStatus.OK, rebajado.getStatusCode());
        assertEquals(0, new BigDecimal("18.00").compareTo(rebajado.getBody().getPrecio()));

        // When: consultarlo (el precio rebajado quedó guardado)
        ResponseEntity<Libro> leido = restTemplate.getForEntity("/api/v1/libros/" + id, Libro.class);

        // Then
        assertEquals(HttpStatus.OK, leido.getStatusCode());
        assertEquals(0, new BigDecimal("18.00").compareTo(leido.getBody().getPrecio()));

        // When: darlo de baja
        ResponseEntity<Void> borrado = restTemplate.exchange(
                "/api/v1/libros/" + id, HttpMethod.DELETE, null, Void.class);

        // Then
        assertEquals(HttpStatus.NO_CONTENT, borrado.getStatusCode());

        // When + Then: ya no existe
        assertEquals(HttpStatus.NOT_FOUND,
                restTemplate.getForEntity("/api/v1/libros/" + id, String.class).getStatusCode());
    }

    @Test
    @DisplayName("Validación en flujo real: precio negativo devuelve 400 con el mensaje")
    void create_shouldReturn400WithMessage_whenPrecioIsNegative() {
        // When
        ResponseEntity<Map<String, String>> respuesta = restTemplate.exchange("/api/v1/libros",
                HttpMethod.POST, new HttpEntity<>(libro("Ficciones", "Borges", "-1.00")),
                new ParameterizedTypeReference<>() {});

        // Then
        assertEquals(HttpStatus.BAD_REQUEST, respuesta.getStatusCode());
        assertEquals("El precio debe ser mayor que cero", respuesta.getBody().get("error"));
    }

    @Test
    @DisplayName("Libro inexistente en flujo real: 404 con el cuerpo de error")
    void findById_shouldReturn404WithBody_whenLibroDoesNotExist() {
        // When
        ResponseEntity<Map<String, String>> respuesta = restTemplate.exchange("/api/v1/libros/12345",
                HttpMethod.GET, null, new ParameterizedTypeReference<>() {});

        // Then
        assertEquals(HttpStatus.NOT_FOUND, respuesta.getStatusCode());
        assertEquals("No existe el libro con id 12345", respuesta.getBody().get("error"));
    }

    @Test
    @DisplayName("Descuento fuera de rango: 400 y el precio no cambia")
    void descuento_shouldReturn400AndKeepPrice_whenPorcentajeIsOutOfRange() {
        // Given
        Long id = repo.save(libro("Rayuela", "Cortázar", "22.90")).getId();

        // When
        ResponseEntity<Map<String, String>> respuesta = restTemplate.exchange(
                "/api/v1/libros/" + id + "/descuento?porcentaje=95", HttpMethod.POST, null,
                new ParameterizedTypeReference<>() {});

        // Then
        assertEquals(HttpStatus.BAD_REQUEST, respuesta.getStatusCode());
        assertEquals(0, new BigDecimal("22.90").compareTo(repo.findById(id).get().getPrecio()));
    }

    @Test
    @DisplayName("Búsqueda por autor en flujo real: solo devuelve los de ese autor")
    void porAutor_shouldReturnOnlyThatAuthor_whenNombreGiven() {
        // Given
        repo.save(libro("Ficciones", "Borges", "12.00"));
        repo.save(libro("El Aleph", "borges", "11.00"));
        repo.save(libro("Rayuela", "Cortázar", "22.90"));

        // When
        ResponseEntity<List<Libro>> respuesta = restTemplate.exchange("/api/v1/libros/por-autor?nombre=BORGES",
                HttpMethod.GET, null, new ParameterizedTypeReference<>() {});

        // Then
        assertEquals(HttpStatus.OK, respuesta.getStatusCode());
        assertEquals(2, respuesta.getBody().size());
    }
