package tut14.repositorio;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import tut14.entidad.Libro;

import java.math.BigDecimal;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Tests del repositorio con @DataJpaTest: solo entidades + repositorios + H2. Los datos se crean en
 * cada test con repo.save(...). Cada test corre en una transacción que se revierte al terminar.
 */
@DataJpaTest
@DisplayName("LibroRepository con @DataJpaTest (datos creados en el propio test)")
class LibroRepositoryTest {

    @Autowired
    private LibroRepository repo;

    private Libro libro(String titulo, String autor, String precio) {
        return new Libro(null, titulo, autor, new BigDecimal(precio));
    }

    @Test
    @DisplayName("save persiste un libro y le asigna id")
    void save_shouldPersistAndAssignId_whenLibroIsNew() {
        // When
        Libro guardado = repo.save(libro("Rayuela", "Cortázar", "22.90"));

        // Then
        assertThat(guardado.getId()).isNotNull();
    }

    @Test
    @DisplayName("findByAutorIgnoreCase ignora mayúsculas y devuelve solo ese autor")
    void findByAutor_shouldReturnOnlyThatAuthor_whenIgnoringCase() {
        // Given
        repo.save(libro("Cien años de soledad", "García Márquez", "18.50"));
        repo.save(libro("Rayuela", "Cortázar", "22.90"));
        repo.save(libro("El coronel no tiene quien le escriba", "GARCÍA MÁRQUEZ", "9.90"));

        // When
        List<Libro> resultado = repo.findByAutorIgnoreCase("garcía márquez");

        // Then
        assertThat(resultado).extracting(Libro::getTitulo)
                .containsExactlyInAnyOrder("Cien años de soledad", "El coronel no tiene quien le escriba");
    }

    @Test
    @DisplayName("findBaratos devuelve los de menos de 20, del más barato al más caro")
    void findBaratos_shouldReturnCheaperThanMax_orderedByPrice() {
        // Given
        repo.save(libro("Caro", "A", "45.00"));
        repo.save(libro("Medio", "B", "15.00"));
        repo.save(libro("Barato", "C", "9.90"));

        // When
        List<Libro> resultado = repo.findBaratos(new BigDecimal("20"));

        // Then
        assertThat(resultado).extracting(Libro::getTitulo).containsExactly("Barato", "Medio");
    }

    @Test
    @DisplayName("findById devuelve Optional vacío cuando no existe")
    void findById_shouldReturnEmpty_whenLibroDoesNotExist() {
        // When + Then
        assertThat(repo.findById(999L)).isEmpty();
    }

    @Test
    @DisplayName("deleteById elimina el libro")
    void deleteById_shouldRemoveLibro_whenLibroExists() {
        // Given
        Long id = repo.save(libro("Para borrar", "X", "1.00")).getId();

        // When
        repo.deleteById(id);

        // Then
        assertThat(repo.findById(id)).isEmpty();
    }

    @Test
    @DisplayName("Aislamiento 1/2: este test inserta un libro")
    void aislamiento_primeraParte_inserta() {
        // Given + When
        repo.save(libro("Solo vive dentro de este test", "X", "5.00"));

        // Then
        assertThat(repo.count()).isEqualTo(1);
    }

    @Test
    @DisplayName("Aislamiento 2/2: el rollback evita ver el libro del otro test")
    void aislamiento_segundaParte_noVeLoDelOtroTest() {
        // When + Then (se ejecute antes o después del otro, la tabla está vacía)
        assertThat(repo.count()).isZero();
    }
}
